-- ============================================================================
-- PSA OSG — Migração consolidada (ROI "antes" + campos do MAPA + nomes)
-- ============================================================================
-- ESCOPO (onde TOCA): SOMENTE o cluster OSG (id 0523512c-...), por UUID:
--   • processes        → frequency, evaluation_status(NULL→'Não avaliado'), name(remove prefixo PX.YY)
--   • process_stages   → error_rate, rework_rate, volume_per_process   (scenario='AS-IS')
--   • etapa_responsaveis → horas                                       (scenario='AS-IS')
--   • etapa_documentos → volume                                        (scenario='AS-IS')
--   • documentos_processo → estruturado (derivado de formato), tipo
--   • job_roles        → type (NULL→'Interno')  [catálogo global; só os 7 papéis usados]
-- NÃO TOCA: outros clusters; datas e justificativas de projeto; job_roles.cluster_id;
--   gargalos (quantificação) e process_improvements (sem input no MAPA); estrutura/etapas
--   (nenhum INSERT/DELETE/DROP — apenas UPDATE de linhas existentes).
-- SEGURANÇA: idempotente (chaveia por id; guards de scenario/cluster/NULL); transação única
--   (tudo-ou-nada). Pré-condição: 33 processos no cluster OSG. ~593 UPDATEs.
-- ============================================================================
BEGIN;

-- ============================================================================
-- PSA 09 — ROI "antes" (AS-IS) quantitativo — cluster OSG
-- Preenche SOMENTE os campos que o motor roiCalculator consome:
--   processes.frequency | process_stages.(error_rate, rework_rate, volume_per_process)
--   etapa_responsaveis.horas  (todos no cenário AS-IS)
-- Escopo: 32 processos / 156 etapas do cluster OSG. P1.03 (piloto) NÃO é tocado.
-- error_rate/rework_rate em escala 0–1 (idêntico ao front: valor% / 100).
-- Valores = estimativas ancoradas no diagnóstico OSG — revisar/validar com a equipe.
-- Idempotente: re-execução regrava os mesmos valores. Chave = id real (UUID).
-- ============================================================================

-- pré-condição: 33 processos no cluster OSG
DO $$ BEGIN
  IF (SELECT count(*) FROM public.processes WHERE cluster_id='0523512c-f980-4236-8a7c-53e06c9c7a80') <> 33 THEN
    RAISE EXCEPTION 'Pré-condição falhou: cluster OSG não tem 33 processos.';
  END IF;
END $$;

