-- 4) verificação pós-update ----------------------------------------------
DO $$ DECLARE v_freq int; v_rate int; v_hrs int; BEGIN
  SELECT count(*) INTO v_freq FROM public.processes WHERE cluster_id='0523512c-f980-4236-8a7c-53e06c9c7a80' AND frequency IS NOT NULL;
  SELECT count(*) INTO v_rate FROM public.process_stages ps JOIN public.processes p ON p.id=ps.process_id
    WHERE p.cluster_id='0523512c-f980-4236-8a7c-53e06c9c7a80' AND ps.scenario='AS-IS' AND ps.rework_rate IS NOT NULL;
  SELECT count(*) INTO v_hrs FROM public.etapa_responsaveis er JOIN public.process_stages ps ON ps.id=er.etapa_id
    JOIN public.processes p ON p.id=ps.process_id WHERE p.cluster_id='0523512c-f980-4236-8a7c-53e06c9c7a80' AND er.scenario='AS-IS' AND er.horas>0;
  RAISE NOTICE 'OSG ROI antes — processos c/ frequency=% | etapas c/ rework_rate=% | responsaveis c/ horas=%', v_freq, v_rate, v_hrs;
  IF v_freq < 32 THEN RAISE EXCEPTION 'frequency preenchida em % processos (esperado >= 32)', v_freq; END IF;
END $$;

